-- Версия 0.74.0. ПЕРЕД выкладкой сайта применены: supabase/sql/clinic_class_v2.sql, supabase/sql/clinic_class_v3.sql,
-- расширено ограничение site_release_items_scope_check (scope game); задеплоена функция release-notify.
-- Пункты с scope game видны только на странице «Игры». Повторный запуск безопасен.
select public.add_site_release('0.74.0','Игры: проектор, закрытие входа, выбор режимов, место участника',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','В игре «Приём пациента» появилась кнопка «Ввести код»: войти в занятие можно и без ссылки, просто назвав код учителя.'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','Во время занятия каждый ординатор видит у себя, на каком он месте среди всех участников; место обновляется само.'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','Учитель заранее выбирает, какие режимы игры «Приём пациента» доступны на занятии — «Обычный», «Хардкор» или оба; участник выбирает один из доступных, а если режим один, играет в нём сразу.'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','Занятие по «Приёму пациента» можно удалить вместе с участниками и баллами: кнопка «Удалить занятие» на экране занятия, с подтверждением.'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','У занятия по «Приёму пациента» есть кнопка «Проектор»: открывает крупное табло с кодом, QR-кодом и местами участников, вход не нужен.'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','На занятии по «Приёму пациента» есть кнопка «Вход закрыт — все зашли»: новые участники больше не входят, а на проекторе остаётся только таблица лидеров.')
  ),
  '2026-12-07 12:00:00+05');
